cat > test_issue2.js << 'EOF'
const mri = require('./lib/index.js');

// Test case: boolean default with boolean flag - the issue is the default key goes into boolean array
const result = mri(['--verbose'], { boolean: ['verbose'], default: { debug: false } });
console.log('Result:', JSON.stringify(result));
console.log('_:', JSON.stringify(result._));

// Simpler test - just boolean default
const result2 = mri(['--verbose'], { default: { debug: false } });
console.log('\nResult2:', JSON.stringify(result2));
console.log('_:', JSON.stringify(result2._));

// What happens in the defaults section:
// opts.default = { debug: false }
// typeof false === 'boolean' → so 'debug' gets pushed into opts.boolean
// Then when parsing --verbose, 'verbose' is not in opts.boolean initially

// Let's trace through toVal more carefully
// When val is boolean (like false), what happens?

// The bug: when a boolean default is set, the key gets added to opts.boolean array
// Then during parsing, the toVal function's boolean branch runs for that key

// Let's test what toVal does with val=false (the boolean value)
console.log('\nTest val=false:');
const x = +false;
console.log('+false =', x, 'isNaN =', isNaN(x));
console.log('x * 0 === 0:', x * 0 === 0);
// This would push 0 into _ !!
EOF
