cat > test_fix.js << 'EOF'
const mri = require('./lib/index.js');

// Test case from the issue: boolean default with boolean flag
console.log("Test 1: --verbose with default { debug: false }");
const result1 = mri(['--verbose'], { boolean: ['verbose'], default: { debug: false } });
console.log('Result:', JSON.stringify(result1));
console.log('_:', JSON.stringify(result1._));
console.log('Expected _: []');
console.log('PASS:', JSON.stringify(result1._) === '[]');

// Test case 2: boolean flag with no value
console.log("\nTest 2: -t moo with boolean: t");
const result2 = mri(['-t', 'moo'], { boolean: 't' });
console.log('Result:', JSON.stringify(result2));
console.log('PASS:', result2.t === true && JSON.stringify(result2._) === '["moo"]');

// Test case 3: --foo=bar should still work
console.log("\nTest 3: --foo=bar with boolean: foo");
const result3 = mri(['--foo=bar'], { boolean: ['foo'] });
console.log('Result:', JSON.stringify(result3));
console.log('PASS:', result3.foo === 'bar');

// Test case 4: --flag=true
console.log("\nTest 4: --flag=true with boolean: flag");
const result4 = mri(['--flag=true'], { boolean: ['flag'] });
console.log('Result:', JSON.stringify(result4));
console.log('PASS:', result4.flag === true);

// Test case 5: --flag=false
console.log("\nTest 5: --flag=false with boolean: flag");
const result5 = mri(['--flag=false'], { boolean: ['flag'] });
console.log('Result:', JSON.stringify(result5));
console.log('PASS:', result5.flag === false);

// Test case 6: --foo with no value (boolean flag)
console.log("\nTest 6: --foo with no value");
const result6 = mri(['--foo']);
console.log('Result:', JSON.stringify(result6));
console.log('PASS:', result6.foo === true && JSON.stringify(result6._) === '[]');

// Test case 7: Multiple boolean flags
console.log("\nTest 7: Multiple boolean flags");
const result7 = mri(['-a', '-b', '-c'], { boolean: ['a', 'b', 'c'] });
console.log('Result:', JSON.stringify(result7));
console.log('PASS:', result7.a === true && result7.b === true && result7.c === true);

// Test case 8: Boolean flag followed by non-flag arg
console.log("\nTest 8: Boolean flag followed by non-flag arg");
const result8 = mri(['--foo', 'bar'], { boolean: ['foo'] });
console.log('Result:', JSON.stringify(result8));
console.log('PASS:', result8.foo === true && JSON.stringify(result8._) === '["bar"]');

// Test case 9: --no-foo should set false
console.log("\nTest 9: --no-foo");
const result9 = mri(['--no-foo']);
console.log('Result:', JSON.stringify(result9));
console.log('PASS:', result9.foo === false);

// Test case 10: Boolean default only (no boolean flag supplied)
console.log("\nTest 10: Boolean default only");
const result10 = mri([], { default: { debug: false } });
console.log('Result:', JSON.stringify(result10));
console.log('PASS:', result10.debug === false && JSON.stringify(result10._) === '[]');
EOF
